from lfx.custom.custom_component.component import Component
from lfx.io import MessageInput, MessageTextInput, StrInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message

import os, csv, json, re, time, uuid, random, hashlib
from pathlib import Path
from datetime import datetime

HOME = Path(os.environ.get("OBS_HOME", str(Path.home() / ".langflow_observabilite")))
EXEC_F, STEP_F, ALERT_F = HOME / "executions.csv", HOME / "steps.csv", HOME / "alerts.csv"
EXEC_COLS = ["correlation_id", "timestamp", "utilisateur", "statut", "duree_totale_ms", "tokens_in", "tokens_out", "cout_usd", "intent", "outil", "nb_etapes", "erreur", "question_masquee"]
STEP_COLS = ["correlation_id", "timestamp", "etape", "type", "nom", "duree_ms", "statut", "tokens_in", "tokens_out", "cout_usd", "detail_masque"]
ALERT_COLS = ["timestamp", "alerte", "valeur", "seuil", "message"]

PII = [(re.compile(r"[\w\.\-+]+@[\w\-]+\.[\w\.\-]+"), "[EMAIL]"),
       (re.compile(r"(?i)\b(mot de passe|password|mdp|pwd)\b\s*(?:est|:|=)?\s*\S+"), r"\1 [SECRET]"),
       (re.compile(r"\b(?:\d[ -]?){13,19}\b"), "[CARTE]")]


def mask(t):
    t = str(t or "")
    for rx, rep in PII:
        t = rx.sub(rep, t)
    return t


def append_csv(path, cols, row):
    path.parent.mkdir(parents=True, exist_ok=True)
    new = not path.exists()
    with open(path, "a", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=cols, extrasaction="ignore")
        if new:
            w.writeheader()
        w.writerow(row)


def read_csv(path):
    if not path.exists():
        return []
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def fnum(x, d=0.0):
    try:
        return float(x)
    except Exception:
        return d


def get_state(d):
    return dict(getattr(d, "data", d)) if d is not None else {}


SIM_F = HOME / "simulation.txt"


def get_sim():
    try:
        return SIM_F.read_text(encoding="utf-8").strip().lower() or "aucune"
    except Exception:
        return "aucune"

TICKET_F = HOME / "tickets.csv"
TICKET_COLS = ["ticket_id", "correlation_id", "timestamp", "utilisateur", "priorite", "resume_masque", "order_id"]


def seed_demo():
    rnd = random.Random(42)
    base = int(time.time()) - 3600
    for i in range(12):
        bad = i in (3, 7, 9)
        dur = rnd.randint(1800, 3800) + (5200 if i in (5, 6, 11) else 0)
        ti, to = rnd.randint(350, 600), rnd.randint(80, 200)
        append_csv(EXEC_F, EXEC_COLS, {"correlation_id": "REQ-DEMO%02d" % i, "timestamp": datetime.fromtimestamp(base + i * 240).isoformat(timespec="seconds"),
                                       "utilisateur": rnd.choice(["amina", "youssef", "sara"]), "statut": "erreur" if bad else "succes", "duree_totale_ms": dur,
                                       "tokens_in": ti, "tokens_out": to, "cout_usd": round(ti * 0.15 / 1e6 + to * 0.6 / 1e6, 6), "intent": "", "outil": "get_order_status",
                                       "nb_etapes": 3, "erreur": "Service indisponible (demo)" if bad else "", "question_masquee": "demande demo"})


def kpis(rows, seuil_lat, seuil_ech, budget):
    n = len(rows)
    ok = sum(1 for r in rows if r["statut"] == "succes")
    durs = sorted(fnum(r["duree_totale_ms"]) for r in rows)
    k = {"n": n, "succes": 100.0 * ok / n, "echec": 100.0 * (n - ok) / n, "lat": sum(durs) / n, "p95": durs[min(n - 1, int(0.95 * n))],
         "cout": sum(fnum(r["cout_usd"]) for r in rows)}
    al = []
    if k["lat"] > seuil_lat:
        al.append(("Alerte Latence", "%.0f ms" % k["lat"], "%d ms" % seuil_lat))
    if k["echec"] > seuil_ech:
        al.append(("Alerte Taux d'échec", "%.1f %%" % k["echec"], "%d %%" % seuil_ech))
    if k["cout"] > budget:
        al.append(("Alerte Coût", "$%.4f" % k["cout"], "$%.2f" % budget))
    return k, al


def fire(alerts, webhook):
    """Archive les alertes (anti-spam 10 min) et notifie le webhook."""
    hist, new, now = read_csv(ALERT_F), [], time.time()
    for a in alerts:
        last = [h for h in hist if h["alerte"] == a[0]]
        if last:
            try:
                if now - datetime.fromisoformat(last[-1]["timestamp"]).timestamp() < 600:
                    continue
            except Exception:
                pass
        append_csv(ALERT_F, ALERT_COLS, {"timestamp": datetime.now().isoformat(timespec="seconds"), "alerte": a[0], "valeur": a[1], "seuil": a[2], "message": "%s: %s > %s" % a})
        new.append(a)
    note = ""
    if new and (webhook or "").strip():
        msg = "ALERTE agent support - " + " | ".join("%s: %s (seuil %s)" % a for a in new)
        note = "webhook: échec"
        import httpx
        for i in range(3):
            try:
                if httpx.post(webhook.strip(), json={"text": msg, "content": msg}, timeout=10).status_code < 300:
                    note = "webhook: envoyé"
                    break
            except Exception:
                pass
            time.sleep(min(2 ** i, 3))
    return new, note


def dashboard_md(rows, k, al, note, n_win):
    md = ["# Dashboard de supervision - Agent Support", "", "Fenêtre: **%d** dernières exécutions" % k["n"], "",
          "| Taux de succès | Latence moyenne | Latence p95 | Coût total |", "|---|---|---|---|",
          "| **%.1f %%** | **%.0f ms** | %.0f ms | **$%.4f** |" % (k["succes"], k["lat"], k["p95"], k["cout"]), "", "## Alertes", ""]
    if al:
        md += ["| Alerte | Valeur | Seuil |", "|---|---|---|"] + ["| %s | %s | %s |" % a for a in al]
        if note:
            md += ["", "_%s_" % note]
    else:
        md.append("Aucune alerte active.")
    hist = read_csv(ALERT_F)[-5:]
    if hist:
        md += ["", "**Dernières alertes déclenchées:**"] + ["- %s - %s" % (h["timestamp"].replace("T", " "), h["message"]) for h in reversed(hist)]
    md += ["", "## Dernières exécutions", "", "| Correlation ID | Statut | Date/Heure | Utilisateur | Durée | Coût |", "|---|---|---|---|---|---|"]
    for r in reversed(rows[-10:]):
        md.append("| %s | %s | %s | %s | %s ms | $%s |" % (r["correlation_id"], r["statut"], r["timestamp"].replace("T", " "), r["utilisateur"], r["duree_totale_ms"], r["cout_usd"]))
    md += ["", "Fichiers (importables dans Google Sheets): `%s`, `%s`, `%s`" % (EXEC_F, STEP_F, TICKET_F)]
    return "\n".join(md)




def sess_f(sid):
    return HOME / "sessions" / (re.sub(r"[^\w\-]", "_", str(sid or "anonyme"))[:80] + ".json")


def diag():
    n = len(read_csv(EXEC_F))
    return "logs: %s (%d executions enregistrees, fichier %s)" % (HOME, n, "present" if EXEC_F.exists() else "absent")




def make_cid(sid, text, ts):
    return "REQ-" + hashlib.sha1(("%s|%s|%s" % (sid, text, ts)).encode("utf-8")).hexdigest()[:6].upper()


class ObsStart(Component):
    display_name = "Observabilité · Correlation ID"
    description = "Crée un Correlation ID unique (REQ-xxxxxx) pour chaque requête, l'ajoute au message et démarre le chronomètre."
    icon = "fingerprint"
    name = "ObsStart"

    inputs = [
        MessageInput(name="message", display_name="Message du client", input_types=["Message"]),
        StrInput(name="simulation", display_name="Simulation de panne: aucune | latence | erreur", value="aucune",
                 info="Pour tester les alertes: 'latence' = chaque outil +4 s, 'erreur' = les outils échouent."),
    ]
    outputs = [
        Output(display_name="Message + ID", name="message_out", method="out_message", group_outputs=True),
        Output(display_name="Meta (Correlation ID)", name="meta", method="out_meta", group_outputs=True),
    ]

    def _ident(self):
        m = self.message
        text = str(getattr(m, "text", m) or "").strip()
        sid = str(getattr(m, "session_id", "") or "anonyme")
        ts = str(getattr(m, "timestamp", "") or "")
        return make_cid(sid, text, ts), sid, text, m

    def out_message(self) -> Message:
        cid, sid, text, m = self._ident()
        try:
            SIM_F.parent.mkdir(parents=True, exist_ok=True)
            SIM_F.write_text((self.simulation or "aucune").strip().lower(), encoding="utf-8")
        except Exception:
            pass
        try:  # filet de securite: le Logger retrouve le Correlation ID par session meme si la connexion Meta manque
            p = sess_f(sid)
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(json.dumps({"correlation_id": cid, "utilisateur": sid, "question": text, "started": time.time()}), encoding="utf-8")
        except Exception:
            pass
        self.status = cid
        return Message(text="[%s] %s" % (cid, text), sender="User", sender_name="User", session_id=sid)

    def out_meta(self) -> Data:
        cid, sid, text, m = self._ident()
        return Data(data={"correlation_id": cid, "utilisateur": sid, "question": text, "started": time.time()})

