DEFAULT_ORDERS = json.dumps({
    "CMD-1001": {"statut": "expediee", "detail": "Expediee le 22/10, arrivee prevue le 27/10 (transporteur Amana)."},
    "CMD-1002": {"statut": "en_preparation", "detail": "En preparation, expedition prevue demain."},
    "CMD-1003": {"statut": "livree", "detail": "Livree le 20/10."},
    "CMD-1004": {"statut": "bloquee", "detail": "Paiement refuse, commande bloquee."}}, ensure_ascii=False, indent=1)


class ToolStatutCommande(Component):
    display_name = "Outil · Statut commande"
    description = "Retourne le statut d'une commande à partir de son numéro CMD-xxxx. À utiliser pour tout suivi de commande."
    icon = "package-search"
    name = "ToolStatutCommande"

    inputs = [
        MessageTextInput(name="order_id", display_name="Numéro de commande", info="Ex: CMD-1002", tool_mode=True),
        MultilineInput(name="orders_db", display_name="Base commandes (JSON)", value=DEFAULT_ORDERS, advanced=True),
    ]
    outputs = [Output(display_name="Résultat", name="result", method="get_order_status")]

    def get_order_status(self) -> Message:
        try:
            return self._get_order_status()
        except Exception as e:
            return Message(text=json.dumps({"erreur": str(e)}, ensure_ascii=False))

    def _get_order_status(self) -> Message:
        sim = get_sim()
        if sim == "latence":
            time.sleep(4)
        if sim == "erreur":
            raise RuntimeError("Service commandes indisponible (simulation)")
        try:
            db = json.loads(self.orders_db)
        except Exception:
            db = json.loads(DEFAULT_ORDERS)
        oid = str(getattr(self.order_id, "text", self.order_id) or "").upper().strip()
        res = db.get(oid) or {"statut": "introuvable", "detail": "Aucune commande avec ce numero."}
        return Message(text=json.dumps(res, ensure_ascii=False))

