    description = "Cherche la réponse à une question générale (livraison, retour, paiement, garantie, horaires, compte) dans la FAQ de la boutique."
    icon = "book-open"
    name = "ToolFAQ"

    inputs = [
        MessageTextInput(name="query", display_name="Question", info="Question générale du client", tool_mode=True),
        MultilineInput(name="faq_db", display_name="FAQ (mots-clés | réponse)", value=DEFAULT_FAQ, advanced=True),
    ]
    outputs = [Output(display_name="Résultat", name="result", method="search_faq")]

    def search_faq(self) -> Message:
        try:
            return self._search_faq()
        except Exception as e:
            return Message(text=json.dumps({"erreur": str(e)}, ensure_ascii=False))

    def _search_faq(self) -> Message:
        sim = get_sim()
        if sim == "latence":
            time.sleep(4)
        if sim == "erreur":
            raise RuntimeError("Service FAQ indisponible (simulation)")
        qs = set(re.findall(r"\w{4,}", str(getattr(self.query, "text", self.query) or "").lower()))
        best, score = "", 0
        for line in (self.faq_db or "").splitlines():
            if "|" in line:
                kw, ans = line.split("|", 1)
                sc = len(qs & set(kw.lower().split()))
                if sc > score:
                    best, score = ans.strip(), sc
        res = {"reponse": best} if best else {"reponse": "", "note": "Aucune reponse FAQ trouvee, creer un ticket."}
