    ]
    outputs = [Output(display_name="Résultat", name="result", method="create_ticket")]

    def create_ticket(self) -> Message:
        try:
            return self._create_ticket()
        except Exception as e:
            return Message(text=json.dumps({"erreur": str(e)}, ensure_ascii=False))

    def _create_ticket(self) -> Message:
        g = lambda v: str(getattr(v, "text", v) or "").strip()
        sim = get_sim()
        if sim == "latence":
            time.sleep(4)
        if sim == "erreur":
            raise RuntimeError("Service tickets indisponible (simulation)")
