def _get(o, k, d=None):
    return o.get(k, d) if isinstance(o, dict) else getattr(o, k, d)


def extract_tools(msg):
    out = []
    for blk in (getattr(msg, "content_blocks", None) or []):
        for c in (_get(blk, "contents", []) or []):
            if _get(c, "type") == "tool_use":
                out.append({"name": _get(c, "name") or "outil", "input": _get(c, "tool_input") or {}, "output": _get(c, "output"),
                            "error": _get(c, "error"), "duration": _get(c, "duration")})
    return out


class LoggerObs(Component):
    display_name = "Observabilité · Logger"
    description = "Lit les appels d'outils de l'agent, mesure durée et coût, écrit executions.csv et steps.csv (sans données sensibles)."
    icon = "scroll-text"
    name = "LoggerObs"

    inputs = [
        MessageInput(name="response", display_name="Réponse de l'agent", input_types=["Message"]),
        DataInput(name="meta", display_name="Meta (Correlation ID)", input_types=["Data"]),
        StrInput(name="price_in", display_name="Prix entrée (USD / 1M tokens)", value="0.15", advanced=True),
        StrInput(name="price_out", display_name="Prix sortie (USD / 1M tokens)", value="0.60", advanced=True),
        IntInput(name="prompt_chars", display_name="Taille du prompt système (caractères, pour estimer les tokens)", value=1500, advanced=True),
        BoolInput(name="afficher_trace", display_name="Afficher la trace sous la réponse", value=True, advanced=True),
    ]
    outputs = [Output(display_name="Réponse + trace", name="reponse", method="log_run")]

    def log_run(self) -> Message:
        meta, resp = get_state(self.meta), self.response
        if not meta.get("correlation_id"):
            try:
                p = sess_f(str(getattr(resp, "session_id", "") or "anonyme"))
                if not p.exists():  # a defaut: la session la plus recente
                    p = max(p.parent.glob("*.json"), key=lambda q: q.stat().st_mtime)
                meta = json.loads(p.read_text(encoding="utf-8"))
            except Exception:
                meta = {}
        answer = str(getattr(resp, "text", resp) or "").strip()
        tools = extract_tools(resp)
        cid = meta.get("correlation_id", "REQ-INCONNU")
        total = int((time.time() - meta.get("started", time.time())) * 1000)
        tool_ms = sum(int(t["duration"] or 0) for t in tools)
        n_calls = 2 if tools else 1
        q = len(meta.get("question", "")) + 12
        t_out = sum(len(str(t["output"] or "")) for t in tools)
        t_arg = sum(len(json.dumps(t["input"], ensure_ascii=False)) for t in tools)
        ti = int(((int(self.prompt_chars) + q) * n_calls + (t_out + t_arg) * (n_calls - 1)) / 4)
        to = int((len(answer) + t_arg) / 4)
        pin, pout = fnum(self.price_in, 0.15), fnum(self.price_out, 0.60)
        cout = round(ti * pin / 1e6 + to * pout / 1e6, 6)
        steps = [{"etape": 1, "type": "llm", "nom": "agent_llm (%d appel%s)" % (n_calls, "s" if n_calls > 1 else ""), "duree_ms": max(0, total - tool_ms), "statut": "succes",
                  "tokens_in": ti, "tokens_out": to, "cout_usd": cout, "detail": "tokens estimes (~4 car./token)"}]
        err = ""
        for t in tools:
            outs = str(t["output"] or "")
            bad = bool(t["error"]) or '"erreur"' in outs or outs.lower().startswith(("error", "erreur"))
            if bad and not err:
                err = str(t["error"] or outs)[:300]
            steps.append({"etape": len(steps) + 1, "type": "outil", "nom": t["name"], "duree_ms": int(t["duration"] or 0), "statut": "erreur" if bad else "succes",
                          "tokens_in": 0, "tokens_out": 0, "cout_usd": 0.0,
                          "detail": "args=%s -> %s" % (json.dumps(t["input"], ensure_ascii=False), err if bad else t["output"])})
        status = "erreur" if (err or not answer) else "succes"
        if not answer and not err:
            err = "reponse vide"
        now = datetime.now().isoformat(timespec="seconds")
        for s in steps:
            append_csv(STEP_F, STEP_COLS, dict(s, correlation_id=cid, timestamp=now, detail_masque=mask(s["detail"])))
        append_csv(EXEC_F, EXEC_COLS, {"correlation_id": cid, "timestamp": now, "utilisateur": meta.get("utilisateur", ""), "statut": status, "duree_totale_ms": total,
                                       "tokens_in": ti, "tokens_out": to, "cout_usd": cout, "intent": "", "outil": ",".join(dict.fromkeys(t["name"] for t in tools)),
                                       "nb_etapes": len(steps), "erreur": mask(err), "question_masquee": mask(meta.get("question", ""))})
        lines = [answer]
        if self.afficher_trace:
            lines += ["", "---", "`%s` · %s · %d ms · %d étapes · ~$%.6f (tokens estimés)" % (cid, status, total, len(steps), cout)]
            for s in steps:
                lines.append("- %s `%s` %d ms %s" % ("🔧" if s["type"] == "outil" else "🧠", s["nom"], s["duree_ms"], "✓" if s["statut"] == "succes" else "✗"))
            lines += ["", "_%s_" % diag()]
        self.status = "%s %s" % (cid, status)
        return Message(text="\n".join(lines), sender="Machine", sender_name="AI", session_id=str(getattr(resp, "session_id", "") or ""))

