class AlertCheck(Component):
    display_name = "Observabilité · 3 Alertes"
    description = "Évalue latence, taux d'échec et coût sur les N dernières exécutions, ajoute l'alerte sous la réponse et notifie un webhook."
    icon = "bell-ring"
    name = "AlertCheck"

    inputs = [
        MessageInput(name="message", display_name="Réponse + trace", input_types=["Message"]),
        IntInput(name="fenetre", display_name="Fenêtre: N dernières exécutions", value=100),
        IntInput(name="seuil_latence_ms", display_name="Alerte Latence: seuil moyenne (ms)", value=5000),
        IntInput(name="seuil_echec_pct", display_name="Alerte Taux d'échec: seuil (%)", value=20),
        StrInput(name="budget_usd", display_name="Alerte Coût: budget (USD)", value="0.50"),
        StrInput(name="webhook_url", display_name="Webhook Slack/Discord/Teams (optionnel)", value="", advanced=True),
    ]
    outputs = [Output(display_name="Réponse finale", name="final", method="check")]

    def check(self) -> Message:
        m = self.message
        text = str(getattr(m, "text", m) or "")
        rows = read_csv(EXEC_F)[-max(1, int(self.fenetre)):]
        out = [text]
        if rows:
            k, al = kpis(rows, int(self.seuil_latence_ms), int(self.seuil_echec_pct), fnum(self.budget_usd, 0.5))
            fire(al, self.webhook_url)
            for a in al:
                out.append("⚠️ **%s**: %s (seuil %s)" % a)
            self.status = "%d alerte(s)" % len(al)
        return Message(text="\n".join(out), sender="Machine", sender_name="AI", session_id=str(getattr(m, "session_id", "") or ""))

